145	        // The household id is deterministic: owners that share a (normalized lastName, postcode)
146	        // share it automatically. It feeds the identity key and the household-duplicate rule below.
147	        owner.setHouseholdId(this.clinicService.computeHouseholdId(owner));
148	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
149	        boolean householdExists = this.clinicService.existsOwnerInHousehold(owner.getHouseholdId());
150	        // Household duplicate: another owner already shares this (lastName, postcode). Rejected unless
151	        // the caller declares they share the household ('sharesHousehold' only bypasses this block).
152	        if (householdExists && !sharesHousehold) {
153	            return new ResponseEntity<>(HttpStatus.CONFLICT);
154	        }
155	        // Hard duplicate detection is consolidated into the owner's derived identity key (see
156	        // Owner#getIdentityKey): reject only when the new owner's whole key matches an existing one.
157	        if (this.clinicService.existsOwnerWithIdentityKey(owner.getIdentityKey())) {
