37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    /**
41	     * The fixed list of public holidays that a registration date must roll forward past, in addition
42	     * to weekends.
43	     */
44	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
45	        LocalDate.of(2026, 1, 1),
46	        LocalDate.of(2026, 1, 26),
47	        LocalDate.of(2026, 4, 25),
48	        LocalDate.of(2026, 12, 25),
49	        LocalDate.of(2026, 12, 28));
50	
51	    @Column(name = "title")
52	    private String title;
53	
54	    @Column(name = "address")
55	    @NotEmpty
56	    private String address;
57	
58	    @Column(name = "address_line1")
59	    private String addressLine1;
60	
61	    @Column(name = "address_line2")
62	    private String addressLine2;
63	
64	    @Column(name = "city")
65	    @NotEmpty
66	    private String city;
67	
68	    @Column(name = "telephone")
69	    @NotEmpty
70	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ followed by 8 to 15 digits)")
71	    private String telephone;
72	
73	    @Column(name = "email")
74	    private String email;
75	
76	    @Column(name = "postcode")
77	    private String postcode;
78	
79	    @Column(name = "registration_date", columnDefinition = "DATE")
80	    private LocalDate registrationDate;
81	
82	    @Column(name = "birth_date", columnDefinition = "DATE")
83	    private LocalDate birthDate;
84	
85	    @Column(name = "customer_code")
86	    private String customerCode;
87	
88	    @Column(name = "household_id")
89	    private String householdId;
90	
91	    @Column(name = "namesake_count")
92	    private Integer namesakeCount;
93	
94	    @Column(name = "possible_duplicate")
95	    private Boolean possibleDuplicate;
96	
97	    @Column(name = "possible_duplicate_of")
98	    private Integer possibleDuplicateOf;
99	
100	    @Column(name = "deleted")
101	    private boolean deleted;
102	
103	    @Transient
104	    private Integer householdSize;
105	
106	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
107	    private Set<Pet> pets;
108	
109	    public String getTitle() {
110	        return this.title;
111	    }
112	
113	    public void setTitle(String title) {
114	        this.title = title;
115	    }
116	
117	    /**
118	     * Derives the owner's salutation for the read-only {@code salutation} field: the title, a single
119	     * space and the lastName when a title is present (e.g. {@code 'DR Who'}), or just the lastName
120	     * when no title was supplied.
121	     */
122	    @Transient
123	    public String getSalutation() {
124	        if (this.title == null || this.title.isBlank()) {
125	            return getLastName();
126	        }
127	        return this.title + " " + getLastName();
128	    }
129	
130	    public String getAddress() {
131	        return this.address;
132	    }
133	
134	    public void setAddress(String address) {
135	        this.address = address;
136	    }
137	
138	    public String getAddressLine1() {
139	        return this.addressLine1;
140	    }
141	
142	    public void setAddressLine1(String addressLine1) {
143	        this.addressLine1 = addressLine1;
144	    }
145	
146	    public String getAddressLine2() {
147	        return this.addressLine2;
148	    }
149	
150	    public void setAddressLine2(String addressLine2) {
151	        this.addressLine2 = addressLine2;
152	    }
153	
154	    public String getCity() {
155	        return this.city;
156	    }
157	
158	    public void setCity(String city) {
159	        this.city = city;
160	    }
161	
162	    public String getTelephone() {
163	        return this.telephone;
164	    }
165	
166	    public void setTelephone(String telephone) {
167	        this.telephone = telephone;
168	    }
169	
170	    public String getEmail() {
171	        return this.email;
172	    }
173	
174	    public void setEmail(String email) {
175	        this.email = email == null ? null : email.toLowerCase();
176	    }
177	
178	    public String getPostcode() {
179	        return this.postcode;
180	    }
181	
182	    public void setPostcode(String postcode) {
183	        this.postcode = postcode;
184	    }
185	
186	    public LocalDate getRegistrationDate() {
187	        return this.registrationDate;
188	    }
189	
190	    public void setRegistrationDate(LocalDate registrationDate) {
191	        this.registrationDate = registrationDate;
192	    }
193	
194	    public LocalDate getBirthDate() {
195	        return this.birthDate;
196	    }
197	
198	    public void setBirthDate(LocalDate birthDate) {
199	        this.birthDate = birthDate;
200	    }
201	
202	    /**
203	     * Derives the owner's age band from the birth date, measured against the registration date:
204	     * {@code 'MINOR'} when under 18, {@code 'ADULT'} for 18 to 64 inclusive, and {@code 'SENIOR'}
205	     * from 65 on. Returns {@code null} when either the birth date or the registration date is absent,
206	     * so an owner created without a birth date has no age band.
207	     */
208	    @Transient
209	    public String getAgeBand() {
210	        if (this.birthDate == null || this.registrationDate == null) {
211	            return null;
212	        }
213	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
214	        if (age < 18) {
215	            return "MINOR";
216	        }
217	        return age < 65 ? "ADULT" : "SENIOR";
218	    }
219	
220	    public String getCustomerCode() {
221	        return this.customerCode;
222	    }
223	
224	    public void setCustomerCode(String customerCode) {
225	        this.customerCode = customerCode;
226	    }
