237	        return this.namesakeCount;
238	    }
239	
240	    public void setNamesakeCount(Integer namesakeCount) {
241	        this.namesakeCount = namesakeCount;
242	    }
243	
244	    /**
245	     * The number of owners belonging to this owner's household (owners sharing this owner's
246	     * household id, including this owner). Not persisted: it is a live count populated at read
247	     * time and feeds the {@code membershipPoints} calculation. Null when it has not been resolved.
248	     */
