250	        return this.householdSize;
251	    }
252	
253	    public void setHouseholdSize(Integer householdSize) {
254	        this.householdSize = householdSize;
255	    }
256	
257	    /**
258	     * Whether this owner was flagged a possible (soft-match) duplicate at creation: it was not a
259	     * hard duplicate, yet it shared an existing owner's lastName and postcode while carrying a
260	     * different telephone. False when no such match existed.
261	     */
262	    public Boolean getPossibleDuplicate() {
263	        return this.possibleDuplicate;
264	    }
265	
266	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
267	        this.possibleDuplicate = possibleDuplicate;
268	    }
269	
270	    /**
271	     * The id of the existing owner this owner soft-matches (same lastName and postcode, different
272	     * telephone), or {@code null} when it is not a possible duplicate.
273	     */
274	    public Integer getPossibleDuplicateOf() {
275	        return this.possibleDuplicateOf;
276	    }
277	
278	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
279	        this.possibleDuplicateOf = possibleDuplicateOf;
280	    }
281	
282	    /**
283	     * Whether this owner has been soft-deleted. A newly created owner is not deleted; a
284	     * {@code DELETE /api/owners/{id}} flags it deleted while retaining the row. Deleted owners are
285	     * ignored by the create endpoint's duplicate and identity checks.
286	     */
287	    public boolean isDeleted() {
288	        return this.deleted;
289	    }
290	
291	    public void setDeleted(boolean deleted) {
292	        this.deleted = deleted;
293	    }
294	
295	    /**
296	     * The owner's derived identity key, used as the single basis for duplicate detection:
297	     * the normalized telephone, the email (empty when absent) and the household id (empty
298	     * when absent), joined with {@code '|'}. Two owners are duplicates only when their whole
299	     * identity keys are equal, so any single differing component (telephone, email or
300	     * household) yields distinct keys and is allowed. Derived from persisted fields, so it is
301	     * not itself a persistent column.
302	     */
303	    @Transient
304	    public String getIdentityKey() {
305	        return (this.telephone == null ? "" : this.telephone)
306	            + "|" + (this.email == null ? "" : this.email)
307	            + "|" + (this.householdId == null ? "" : this.householdId);
308	    }
309	
310	    /**
311	     * Establishes the effective registration date at persist time, so the create-time default
312	     * applies to any persistence path.
313	     */
314	    @PrePersist
315	    protected void defaultRegistrationDate() {
316	        resolveRegistrationDate();
317	    }
318	
319	    /**
320	     * Resolves this owner's effective registration date and stores it: the supplied value is used, or
321	     * the server's current date when none was supplied, and the result is rolled forward onto a
322	     * business day (a Saturday, Sunday or public holiday rolls forward to the next business day).
323	     * Returns the resolved date.
324	     * Idempotent, so it is safe to call from both the create flow and the persist hook.
325	     */
326	    public LocalDate resolveRegistrationDate() {
327	        LocalDate effective = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
328	        this.registrationDate = toBusinessDay(effective);
329	        return this.registrationDate;
330	    }
331	
332	    /**
333	     * Derives the fiscal year that a date falls in, where each fiscal year starts on 1 July and is
334	     * identified by the calendar year in which it ends: a date from July onwards belongs to the
335	     * fiscal year ending in the following calendar year (e.g. 2 July 2026 gives 2027), while a date
336	     * from January to June belongs to the fiscal year ending in its own calendar year. Returns
337	     * {@code null} when the date is absent.
338	     */
339	    public static Integer fiscalYear(LocalDate date) {
340	        if (date == null) {
341	            return null;
342	        }
343	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
344	    }
345	
346	    /**
347	     * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
348	     * holiday is advanced to the next non-holiday weekday, while any other weekday (and {@code null})
349	     * is returned unchanged. Applying this to a date that is already a business day is a no-op, so it
350	     * is safe to call more than once.
351	     */
352	    public static LocalDate toBusinessDay(LocalDate date) {
353	        if (date == null) {
354	            return null;
355	        }
356	        LocalDate result = date;
357	        while (isWeekend(result) || PUBLIC_HOLIDAYS.contains(result)) {
358	            result = result.plusDays(1);
359	        }
360	        return result;
361	    }
362	
363	    private static boolean isWeekend(LocalDate date) {
364	        return switch (date.getDayOfWeek()) {
365	            case SATURDAY, SUNDAY -> true;
366	            default -> false;
367	        };
368	    }
369	
370	    protected Set<Pet> getPetsInternal() {
371	        if (this.pets == null) {
372	            this.pets = new HashSet<>();
373	        }
374	        return this.pets;
375	    }
376	
377	    protected void setPetsInternal(Set<Pet> pets) {
378	        this.pets = pets;
379	    }
380	
381	    public List<Pet> getPets() {
382	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
383	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
384	        return Collections.unmodifiableList(sortedPets);
385	    }
386	
387	    public void setPets(List<Pet> pets) {
388	        this.pets = new HashSet<>(pets);
389	    }
390	
391	    public void addPet(Pet pet) {
392	        getPetsInternal().add(pet);
393	        pet.setOwner(this);
394	    }
395	
396	    /**
397	     * Return the Pet with the given name, or null if none found for this Owner.
398	     *
399	     * @param name to test
400	     * @return true if pet name is already in use
401	     */
402	    public Pet getPet(String name) {
403	        return getPet(name, false);
404	    }
405	
406	    /**
407	     * Return the Pet with the given name, or null if none found for this Owner.
408	     *
409	     * @param name to test
410	     * @return true if pet name is already in use
411	     */
412	    public Pet getPet(String name, boolean ignoreNew) {
413	        name = name.toLowerCase();
414	        for (Pet pet : getPetsInternal()) {
415	            if (!ignoreNew || !pet.isNew()) {
416	                String compName = pet.getName();
417	                compName = compName.toLowerCase();
418	                if (compName.equals(name)) {
419	                    return pet;
420	                }
421	            }
422	        }
423	        return null;
424	    }
425	
426	    public Pet getPet(Integer petId) {
427	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
428	    }
429	
430	    @Override
431	    public String toString() {
432	        return new ToStringCreator(this)
433	
434	            .append("id", this.getId())
435	            .append("new", this.isNew())
436	            .append("lastName", this.getLastName())
437	            .append("firstName", this.getFirstName())
438	            .append("address", this.address)
439	            .append("city", this.city)
440	            .append("telephone", this.telephone)
441	            .toString();
442	    }
443	}
