269	    /**
270	     * Builds an owner's customer code formatted {@code '<REGION>-<HASH8>'}, where REGION is the
271	     * region code derived from the owner's postcode (see {@link #deriveRegion(Owner)}) and HASH8 is
272	     * the first 8 upper-case hex characters of the SHA-256 digest over the owner's normalized
273	     * telephone concatenated with its last name (e.g. {@code 'NSW-1A2B3C4D'}). The old per-city
274	     * sequence numbers have been dropped: the identity is now purely region-and-hash.
275	     *
276	     * <p>When the computed code collides with an existing owner's {@code customerCode}, {@code '-<n>'}
277	     * is appended with the smallest {@code n} of 2 or more that makes it unique, so distinct owners
278	     * always receive distinct customer codes.
279	     */
280	    private String generateCustomerCode(Owner owner) {
281	        String base = String.format("%s-%s", deriveRegion(owner), hash8(owner));
282	        Set<String> existing = ownerRepository.findAll().stream()
283	            .map(Owner::getCustomerCode)
284	            .filter(Objects::nonNull)
285	            .collect(Collectors.toSet());
286	        if (!existing.contains(base)) {
287	            return base;
288	        }
289	        for (int n = 2; ; n++) {
290	            String candidate = base + "-" + n;
291	            if (!existing.contains(candidate)) {
292	                return candidate;
293	            }
294	        }
295	    }
296	
297	    /**
298	     * Derives an owner's region code, preferring the postcode: the region whose inclusive 4-digit
299	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) contains the postcode is used first. When
300	     * the postcode is absent or in no known range, it falls back to the fixed city-to-region table
301	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD), returning {@code 'UNKNOWN'} when the
302	     * city is not in the table.
303	     */
304	    private static String deriveRegion(Owner owner) {
305	        String postcode = owner.getPostcode();
306	        if (postcode != null && postcode.matches("^[0-9]{4}$")) {
307	            int value = Integer.parseInt(postcode);
308	            for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
309	                int[] range = entry.getValue();
310	                if (value >= range[0] && value <= range[1]) {
311	                    return entry.getKey();
312	                }
313	            }
314	        }
315	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
316	    }
317	
318	    /**
319	     * Computes an owner's identity hash as the first 8 upper-case hex characters of the SHA-256
320	     * digest over its normalized telephone concatenated with its last name.
321	     */
322	    private static String hash8(Owner owner) {
323	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
324	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
325	        String seed = telephone + lastName;
326	        try {
327	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
328	            byte[] hash = digest.digest(seed.getBytes(StandardCharsets.UTF_8));
329	            StringBuilder sb = new StringBuilder(hash.length * 2);
330	            for (byte b : hash) {
331	                sb.append(String.format("%02X", b));
332	            }
333	            return sb.substring(0, 8);
334	        }
335	        catch (NoSuchAlgorithmException e) {
336	            throw new IllegalStateException("SHA-256 not available", e);
337	        }
338	    }
339	
340	    /**
341	     * Whether any existing owner has the given derived identity key. This is the single basis for
342	     * duplicate detection: a create is rejected only when the whole key matches an existing owner
343	     * exactly. See {@link Owner#getIdentityKey()} for the key's definition.
344	     */
345	    @Override
346	    @Transactional(readOnly = true)
347	    public boolean existsOwnerWithIdentityKey(String identityKey) throws DataAccessException {
348	        if (identityKey == null) {
349	            return false;
350	        }
351	        return ownerRepository.findAll().stream()
352	            .filter(existing -> !existing.isDeleted())
353	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
354	    }
355	
356	    /**
357	     * Finds the id of an existing owner that {@code owner} soft-matches (a possible duplicate): one
358	     * that shares its lastName (case-insensitive) and postcode while carrying a <i>different</i>
359	     * telephone. This is a weaker match than the hard-duplicate identity key, so it is only meaningful
360	     * for an owner that is not itself a hard duplicate. When several owners match, the one with the
361	     * lowest id is returned; {@code null} is returned when there is no match (or lastName/postcode is
362	     * absent), meaning the owner is not a possible duplicate.
363	     */
364	    @Override
365	    @Transactional(readOnly = true)
366	    public Integer findPossibleDuplicateOwnerId(Owner owner) throws DataAccessException {
367	        if (owner == null || owner.getLastName() == null || owner.getPostcode() == null) {
368	            return null;
369	        }
370	        String lastName = owner.getLastName();
371	        String postcode = owner.getPostcode();
372	        String telephone = owner.getTelephone();
373	        return ownerRepository.findAll().stream()
374	            .filter(existing -> !existing.isDeleted())
375	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName())
376	                && postcode.equals(existing.getPostcode())
377	                && !Objects.equals(telephone, existing.getTelephone()))
378	            .map(Owner::getId)
379	            .filter(Objects::nonNull)
380	            .min(Comparator.naturalOrder())
381	            .orElse(null);
382	    }
383	
384	    /**
385	     * Counts the existing owners whose firstName and lastName match the given values
386	     * case-insensitively. Used to record an owner's namesake count at creation time.
387	     */
388	    @Override
389	    @Transactional(readOnly = true)
390	    public int countOwnersByName(String firstName, String lastName) throws DataAccessException {
391	        if (firstName == null || lastName == null) {
392	            return 0;
393	        }
394	        return (int) ownerRepository.findAll().stream()
395	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
396	                && lastName.equalsIgnoreCase(existing.getLastName()))
397	            .count();
398	    }
399	
400	    /**
401	     * Counts the existing owners whose city matches the given value case-insensitively.
402	     * Used to enforce the per-city capacity rule at creation time.
403	     */
404	    @Override
405	    @Transactional(readOnly = true)
406	    public int countOwnersByCity(String city) throws DataAccessException {
407	        if (city == null) {
408	            return 0;
409	        }
410	        return (int) ownerRepository.findAll().stream()
411	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
412	            .count();
413	    }
414	
415	    /**
416	     * Counts the existing owners whose registration date matches the given value.
417	     * Used to enforce the per-day owner creation limit.
418	     */
419	    @Override
420	    @Transactional(readOnly = true)
421	    public int countOwnersByRegistrationDate(LocalDate registrationDate) throws DataAccessException {
422	        if (registrationDate == null) {
423	            return 0;
424	        }
425	        return (int) ownerRepository.findAll().stream()
426	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
427	            .count();
428	    }
429	
430	    /**
431	     * Computes an owner's deterministic household id: the first 12 upper-case hex characters of the
432	     * SHA-256 digest over the owner's normalized last name, a {@code '|'} separator and its postcode
433	     * ({@code normalizedLastName + '|' + postcode}). Owners that share a last name and postcode
434	     * therefore map to the same household id automatically, without any explicit linking. Returns
435	     * {@code null} when the last name or postcode is absent or blank, since no household can be
436	     * formed without both.
437	     */
438	    @Override
439	    @Transactional(readOnly = true)
440	    public String computeHouseholdId(Owner owner) throws DataAccessException {
441	        if (owner == null) {
442	            return null;
443	        }
444	        String normalizedLastName = normalizeHouseholdField(owner.getLastName());
445	        String postcode = owner.getPostcode();
446	        if (normalizedLastName == null || normalizedLastName.isBlank()
447	            || postcode == null || postcode.isBlank()) {
448	            return null;
449	        }
450	        return sha256UpperHex(normalizedLastName + "|" + postcode, 12);
451	    }
452	
453	    /**
454	     * Whether any existing owner already belongs to the household identified by the given
455	     * (deterministic) household id. This is the single basis for the household-duplicate rule:
456	     * owners that share a last name and postcode share a household id, so a matching existing owner
457	     * means the new owner is a household duplicate. Returns {@code false} when the id is absent.
458	     */
459	    @Override
460	    @Transactional(readOnly = true)
461	    public boolean existsOwnerInHousehold(String householdId) throws DataAccessException {
462	        if (householdId == null || householdId.isBlank()) {
463	            return false;
464	        }
465	        return ownerRepository.findAll().stream()
466	            .filter(existing -> !existing.isDeleted())
467	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
468	    }
469	
470	    /**
471	     * Counts the owners that belong to the household identified by the given (deterministic)
472	     * household id, i.e. the number of owners currently sharing it. Used to size a household for
473	     * the membership-points calculation. Returns {@code 0} when the id is absent.
474	     */
475	    @Override
476	    @Transactional(readOnly = true)
477	    public int countOwnersByHouseholdId(String householdId) throws DataAccessException {
478	        if (householdId == null || householdId.isBlank()) {
479	            return 0;
480	        }
481	        return (int) ownerRepository.findAll().stream()
482	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
483	            .count();
484	    }
485	
486	    /**
487	     * Normalizes a household-identity field for comparison by trimming, collapsing internal
488	     * runs of whitespace to a single space and lower-casing, so values that differ only in
489	     * whitespace or letter case are treated as equal.
490	     */
491	    private static String normalizeHouseholdField(String value) {
492	        if (value == null) {
493	            return null;
494	        }
495	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
496	    }
497	
498	    /**
499	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
500	     * UTF-8 bytes of {@code seed}.
501	     */
502	    private static String sha256UpperHex(String seed, int length) {
503	        try {
504	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
505	            byte[] hash = digest.digest(seed.getBytes(StandardCharsets.UTF_8));
506	            StringBuilder sb = new StringBuilder(hash.length * 2);
507	            for (byte b : hash) {
508	                sb.append(String.format("%02X", b));
509	            }
510	            return sb.substring(0, length);
511	        }
512	        catch (NoSuchAlgorithmException e) {
513	            throw new IllegalStateException("SHA-256 not available", e);
514	        }
515	    }
516	
517	    @Override
518	    @Transactional(readOnly = true)
519	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
520	        return ownerRepository.findByLastName(lastName);
521	    }
522	
523	    /**
524	     * Returns the id of the owner previously created for the given idempotency key, or {@code null}
525	     * when the key has not been seen (or is absent), meaning the create should proceed normally.
526	     */
527	    @Override
528	    public Integer findOwnerIdByIdempotencyKey(String idempotencyKey) throws DataAccessException {
529	        if (idempotencyKey == null || idempotencyKey.isBlank()) {
530	            return null;
531	        }
532	        return idempotencyKeys.get(idempotencyKey);
533	    }
534	
535	    /**
536	     * Records that the given idempotency key produced the owner with the given id, so a later create
537	     * repeating the key replays that owner instead of duplicating it. No-op when the key is absent.
538	     */
539	    @Override
540	    public void registerIdempotencyKey(String idempotencyKey, Integer ownerId) throws DataAccessException {
541	        if (idempotencyKey == null || idempotencyKey.isBlank() || ownerId == null) {
542	            return;
543	        }
544	        idempotencyKeys.put(idempotencyKey, ownerId);
545	    }
546	
547	    @Override
548	    @Transactional(readOnly = true)
549	    public Collection<Visit> findVisitsByPetId(int petId) {
550	        return visitRepository.findByPetId(petId);
551	    }
552	
553	    @Override
554	    @Transactional(readOnly = true)
555	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
556	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
557	    }
558	
559	    private <T> T findEntityById(Supplier<T> supplier) {
560	        try {
561	            return supplier.get();
562	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
563	            // Just ignore not found exceptions for Jdbc/Jpa realization
564	            return null;
565	        }
566	    }
567	
568	}
